import edited from './test-media/edited.mp4?inline';
import moovAtEnd from './test-media/moov-at-end.mp4?inline';
import portraitIphone from './test-media/portrait-iphone.mov?inline';
import { describe, expect, it } from 'vitest';
import { bytesOf } from '../test/data-url';
import { readMp4Header, type ByteSource } from './mp4-header';

// Story 12 (ADR 0041, UX-55): the header of an MP4 or MOV file read by the site, on files generated by ffmpeg (an iPhone
// video in portrait, a « moov » box at the end, an edit list) and on boxes written here for the edge cases.

/** A file of test-media, inlined by Vite as a data URL (base64). */
const fixtures: Record<string, string> = {
  'portrait-iphone.mov': portraitIphone,
  'moov-at-end.mp4': moovAtEnd,
  'edited.mp4': edited,
};
const fixture = (name: string) => bytesOf(fixtures[name]!);

const sourceOf = (bytes: Uint8Array): ByteSource => ({
  size: bytes.length,
  read: async (start, end) => bytes.slice(start, end),
});

const u32 = (value: number) => [
  (value >>> 24) & 0xff,
  (value >>> 16) & 0xff,
  (value >>> 8) & 0xff,
  value & 0xff,
];
const ascii = (text: string) => [...text].map((c) => c.charCodeAt(0));
const box = (type: string, ...payload: number[][]) => {
  const content = payload.flat();
  return [...u32(content.length + 8), ...ascii(type), ...content];
};
const identity = [0x10000, 0, 0, 0, 0x10000, 0, 0, 0, 0x40000000].flatMap(u32);
const mvhd = (timescale: number, duration: number) =>
  box(
    'mvhd',
    u32(0),
    u32(0),
    u32(0),
    u32(timescale),
    u32(duration),
    u32(0x10000),
    [1, 0],
    Array(10).fill(0),
    identity,
    Array(24).fill(0),
    u32(2),
  );
const tkhd = (width: number, height: number) =>
  box(
    'tkhd',
    u32(3),
    u32(0),
    u32(0),
    u32(1),
    u32(0),
    u32(0),
    Array(8).fill(0),
    Array(8).fill(0),
    identity,
    u32(width << 16),
    u32(height << 16),
  );
const videoTrack = (width: number, height: number, ...more: number[][]) =>
  box(
    'trak',
    tkhd(width, height),
    ...more,
    box('mdia', box('hdlr', u32(0), u32(0), ascii('vide'), Array(13).fill(0))),
  );
const file = (...boxes: number[][]) =>
  new Uint8Array([...box('ftyp', ascii('isom'), u32(0), ascii('isom')), ...boxes.flat()]);

describe('readMp4Header', () => {
  it('should read the duration and the upright dimensions of a video filmed in portrait by a phone', async () => {
    expect(await readMp4Header(sourceOf(fixture('portrait-iphone.mov')))).toEqual({
      durationMs: 2_600,
      dimensions: { width: 108, height: 192 },
    });
  });

  it('should find the box « moov » at the end of the file', async () => {
    expect(await readMp4Header(sourceOf(fixture('moov-at-end.mp4')))).toEqual({
      durationMs: 3_200,
      dimensions: { width: 160, height: 90 },
    });
  });

  it('should read the duration presented by an edit list', async () => {
    expect((await readMp4Header(sourceOf(fixture('edited.mp4'))))?.durationMs).toBe(2_200);
  });

  it('should take the edit list of the video track over the duration of the movie', async () => {
    const edits = box('edts', box('elst', u32(0), u32(1), u32(9_000), u32(0), u32(0x10000)));
    const bytes = file(box('moov', mvhd(1_000, 40_000), videoTrack(1920, 1080, edits)));

    expect(await readMp4Header(sourceOf(bytes))).toEqual({
      durationMs: 9_000,
      dimensions: { width: 1920, height: 1080 },
    });
  });

  it.each([
    ['a fragmented MP4', file(box('moov', mvhd(1_000, 12_000), videoTrack(1920, 1080), box('mvex')))],
    ['no box « moov »', file(box('mdat', Array(64).fill(0)))],
    ['no video track', file(box('moov', mvhd(1_000, 12_000)))],
    ['a box larger than the file', new Uint8Array([...file(), ...u32(1_000_000), ...ascii('moov')])],
  ])('should read nothing from %s', async (_case, bytes) => {
    expect(await readMp4Header(sourceOf(bytes))).toBeNull();
  });
});
